inline const char* shortKey(const char* key) {
    return key && std::strncmp(key, "EXTRA_Phone", 11) == 0 ? key + 11 : key;
}

inline const char* get(const char* key, bool russian) {
    key = shortKey(key);
    if (key) for (const auto& line : Lines)
        if (std::strcmp(key, line.key) == 0) return russian ? line.ru : line.en;
    return nullptr;
}

inline unsigned count(const char* key) {
    key = shortKey(key);
    if (key) for (const auto& branch : Branches)
        if (std::strcmp(key, branch.key) == 0) return branch.count;
    return 0;
}

